        },
        {
          "position": "right",
          "handles": [
            {
              "id": "output",
              "type": "source",
              "handleType": "output"
            }
          ]
        }
      ],
      "model": {
        "type": "bpmn:IntermediateCatchEvent",
        "eventDefinition": "bpmn:TimerEventDefinition",
        "values": {
          "timerType": "inputs.timerType",
          "timerValue": "inputs.timerValue",
          "timerPreset": "inputs.timerPreset",
          "timerDate": "inputs.timerDate"
        }
      },
      "inputDefinition": {
        "type": "object",
        "properties": {
          "timerType": {
            "type": "string",
            "minLength": 1,
            "errorMessage": "Timer type is required"
          },
          "timerPreset": {
            "type": "string",
            "minLength": 1,
            "errorMessage": "Duration is required"
          },
          "timerValue": {
            "type": "string"
          },
          "timerDate": {
            "type": "string"
          }
        },
        "required": [
          "timerType",
          "timerPreset"
        ],
        "allOf": [
          {
            "if": {
              "properties": {
                "timerType": {
                  "const": "timeDuration"
                },
                "timerPreset": {
                  "const": "custom"
                }
              },
              "required": [
                "timerType",
                "timerPreset"
              ]
            },
            "then": {
              "properties": {
                "timerValue": {
                  "type": "string",
                  "minLength": 1,
                  "pattern": "^P(?!$)(\\d+Y)?(\\d+M)?(\\d+W)?(\\d+D)?(T(?=\\d)(\\d+H)?(\\d+M)?(\\d+S)?)?$",
                  "errorMessage": "Custom duration is required (ISO 8601 format, e.g., PT15M, PT1H, P1D)"
                }
              },
              "required": [
                "timerValue"
              ]
            }
          },
          {
            "if": {
              "properties": {
                "timerType": {
                  "const": "timeDate"
                }
              },
              "required": [
                "timerType"
              ]
            },
            "then": {
              "properties": {
                "timerDate": {
                  "type": "string",
                  "minLength": 1,
                  "errorMessage": "Date is required"
                }
              },
              "required": [
                "timerDate"
              ]
            }
          }
        ]
      },
      "inputDefaults": {
        "timerType": "timeDuration",
        "timerPreset": "PT15M"
      },
      "form": {
        "id": "delay-properties",
        "title": "Delay",
        "sections": [
          {
            "id": "timer",
            "title": "Timer",
            "collapsible": true,
            "defaultExpanded": true,
            "fields": [
              {
                "name": "inputs.timerType",
                "type": "select",
                "label": "Type",
                "options": [
                  {
                    "label": "Duration",
                    "value": "timeDuration"
                  },
                  {
                    "label": "Date",
                    "value": "timeDate"
                  }
                ]
              },
              {
                "name": "inputs.timerPreset",
                "type": "select",
                "label": "Duration",
                "options": [
                  {
                    "label": "5 seconds",
                    "value": "PT5S"
                  },
                  {
                    "label": "15 seconds",
                    "value": "PT15S"
                  },
                  {
                    "label": "30 seconds",
                    "value": "PT30S"
                  },
                  {
                    "label": "1 minute",
                    "value": "PT1M"
                  },
                  {
                    "label": "5 minutes",
                    "value": "PT5M"
                  },
                  {
                    "label": "15 minutes",
                    "value": "PT15M"
                  },
                  {
                    "label": "30 minutes",
                    "value": "PT30M"
                  },
                  {
                    "label": "1 hour",
                    "value": "PT1H"
                  },
                  {
                    "label": "6 hours",
                    "value": "PT6H"
                  },
                  {
                    "label": "12 hours",
                    "value": "PT12H"
                  },
                  {
                    "label": "1 day",
                    "value": "P1D"
                  },
                  {
                    "label": "1 week",
                    "value": "P1W"
                  },
                  {
                    "label": "Custom",
                    "value": "custom"
                  }
                ],
                "rules": [
                  {
                    "id": "duration-presets",
                    "conditions": [
                      {
                        "when": "inputs.timerType",
                        "is": "timeDuration"
                      }
                    ],
                    "effects": {
                      "visible": true
                    }
                  }
                ]
              },
              {
                "name": "inputs.timerValue",
                "type": "custom",
                "component": "iso-expression-field",
                "label": "Custom duration",
                "placeholder": "PT15M",
                "description": "ISO 8601 duration - use the AI button to generate from natural language",
                "componentProps": {
                  "expressionType": "duration",
                  "supportsExpressions": true
                },
                "rules": [
                  {
                    "id": "custom-duration",
                    "conditions": [
                      {
                        "when": "inputs.timerType",
                        "is": "timeDuration"
                      },
                      {
                        "when": "inputs.timerPreset",
                        "is": "custom"
                      }
                    ],
                    "effects": {
                      "visible": true
                    }
                  }
                ]
              },
              {
                "name": "inputs.timerDate",
                "type": "datetime",
                "label": "Value",
                "description": "The date and time when the workflow should continue",
                "rules": [
                  {
                    "id": "date-format",
                    "conditions": [
                      {
                        "when": "inputs.timerType",
                        "is": "timeDate"
                      }
                    ],
                    "effects": {
                      "visible": true
                    }
                  }
                ]
              }
            ]
          }
        ]
      }
    }
  }
}

